def _ledger(data, sequence_first, original_tax, refunds):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            key = (sequence, event.get("revision", 0), pos)
        else:
            key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = raw if original_tax else net
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if refunds and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = {}
    for name in names:
        options[name] = [None] + [row for row in packages[name]
                                  if row["version"] not in blocked.get(name, [])
                                  and (name not in pins or row["version"] == pins[name])]

    best_vector = None
    best = None

    def acyclic(edges):
        active, done = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            for target in edges[name]:
                if not visit(target):
                    return False
            active.remove(name)
            done.add(name)
            return True

        return all(visit(name) for name in edges)

    def consider(index, selected):
        nonlocal best_vector, best
        if index < len(names):
            name = names[index]
            for row in options[name]:
                if row is None:
                    selected.pop(name, None)
                else:
                    selected[name] = row
                consider(index + 1, selected)
            selected.pop(name, None)
            return

        for name, bounds in data["roots"].items():
            row = selected.get(name)
            if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                return

        edges = {name: [] for name in selected}
        for name, row in selected.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in selected or not dep["min"] <= selected[target]["version"] <= dep["max"]:
                    return
                edges[name].append(target)
        if not acyclic(edges):
            return

        reachable = set()
        pending = list(data["roots"])
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in selected:
                return
            reachable.add(name)
            pending.extend(edges[name])
        if reachable != set(selected):
            return

        vector = tuple(selected[name]["version"] if name in selected else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = {name: selected[name]["version"] for name in names if name in selected}

    consider(0, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _component_07(data):
    from itertools import combinations

    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        # At every distinct start, count intervals active at that time.
        if any(sum(job["start"] <= time < job["end"] for job in subset) > 2
               for time in {job["start"] for job in subset}):
            continue

        value = sum(job["value"] for job in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bits.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    start = data["start"]
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                discounted = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((discounted, remaining - 1))
            for duration, next_remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                next_mask = mask | bits.get(dest, 0)
                next_state = (dest, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, next_mask, next_remaining))

    return {"arrival": None}


